def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # Fast aggregates
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    op_rate = op_c / n

    last_op = op[-1]
    last_me = history[-1][0]

    # Recency-weighted opponent cooperation
    wsum = 0.0
    wcoop = 0.0
    for i in range(n):
        w = 1.0 + (i / (n - 1)) * 3.0
        wsum += w
        if op[i] == 'C':
            wcoop += w
    rec_rate = wcoop / wsum

    # Trailing streaks
    sd = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        sd += 1
        i -= 1
    sc = 0
    i = n - 1
    while i >= 0 and op[i] == 'C':
        sc += 1
        i -= 1

    remaining = 100 - n

    # Opportunistic endgame: exploit known nice opponents
    if remaining <= 4:
        if op_rate >= 0.7 and sd == 0:
            return 'D'
        if op_rate <= 0.35:
            return 'D'
        if last_op == 'D' and sd >= 2:
            return 'D'
        return 'C' if op_rate > 0.5 else 'D'

    if remaining <= 10:
        if op_rate >= 0.6 and sd <= 1:
            return 'D'
        if sd >= 2:
            return 'D'
        if rec_rate < 0.35:
            return 'D'
        return 'C'

    if remaining <= 20:
        if sd >= 2:
            return 'D'
        if op_rate <= 0.25:
            return 'D'
        if op_rate >= 0.7:
            return 'C'
        if last_op == 'C' and sc >= 2:
            return 'C'
        return 'D' if rec_rate < 0.4 else 'C'

    # Early-mid game: mostly TFT-with-forgiveness

    # Hard retaliation vs persistent defectors
    if sd >= 3:
        return 'D'

    # Pure always-defect detection
    if n >= 5 and op_c == 0:
        return 'D'

    if sd == 2:
        # Punish but allow escape for likely-forgiving opponents
        if op_c > 0 and rec_rate > 0.4 and rng.random() < 0.3:
            return 'C'
        return 'D'

    if sd == 1:
        # Single recent defection: punish, but mix
        if last_me == 'D':
            # We already retaliated; return to cooperation to break loops
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if op_rate < 0.25:
        return 'D'

    # Occasionally probe/groom nice opponents
    if op_rate > 0.85 and n > 15 and n % 23 == 0:
        return 'D'

    # If we defected last round and they still cooperated, keep cooperating
    if last_me == 'D':
        return 'C'

    # Occasional gentle re-testing when opponent is moderate
    if 0.4 <= op_rate <= 0.7 and n > 30 and n % 17 == 0 and rng.random() < 0.25:
        return 'D'

    return 'C'
